head.script:
scwin.CHART_DATA_URL ="/ui/sample/SBChart/MAP/data/MAP.json";    // data(type:map, json, keys) 조회

scwin.CHART_CONFIG = {
    global: {
        padding: { top: 10, right: 10, bottom: 10, left: 10 },
        animation: { show: true }
    },
    title: { text: "지역별 강수량", position: "top" },
    legend: { show: true, position: "bottom" },
    tooltip: { show: true },
    dataOpts: { keys: { x: "code", value: ["강수량"] } },   // 데이터레벨 옵션(keys) — JSON 대신 스크립트에서
    extend: {
        map: {
            mapUrl: "/websquare/_websquare_/externalJS/sbchart/SIGUNGU.json",  // 지도 데이터
            drillDown: true,                               // 시도 → 시군구 드릴다운
            onclick: function (code, label, data) {        // 지역 클릭 이벤트 (code, label, data)
                scwin.fn_click(label + " (코드 " + code + ")");
            }
        }
    }
};

scwin.onpageload = async function () {
    var res = await $c.sbm.executeDynamic({ id: "sbm_sbchart", action: scwin.CHART_DATA_URL, method: "get", mediatype: "application/json", mode: "asynchronous", isProcessMsg: false });
    var data = res.responseJSON;
    $c.ext.drawChartData("map", data, chartWrap, scwin.CHART_CONFIG);
};
scwin.fn_click = function (msg) { 
	$c.win.alert(msg)
};
